CREATE TABLE IF NOT EXISTS work_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,connection_id BIGINT UNSIGNED NOT NULL,technician_id BIGINT UNSIGNED NOT NULL,status ENUM('scheduled','in_progress','completed','blocked') NOT NULL DEFAULT 'scheduled',scheduled_at DATETIME NOT NULL,completion_notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(connection_id) REFERENCES connections(id),FOREIGN KEY(technician_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS equipment(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,serial_number VARCHAR(120) NOT NULL UNIQUE,model VARCHAR(120) NOT NULL,mac_address VARCHAR(17) UNIQUE,ownership ENUM('isp','customer','sold','rented','loaned') NOT NULL DEFAULT 'isp',connection_id BIGINT UNSIGNED NULL,status ENUM('stock','assigned','faulty','returned') NOT NULL DEFAULT 'stock',FOREIGN KEY(connection_id) REFERENCES connections(id));
CREATE TABLE IF NOT EXISTS stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,equipment_id BIGINT UNSIGNED NOT NULL,connection_id BIGINT UNSIGNED NULL,actor_id BIGINT UNSIGNED NOT NULL,action VARCHAR(40) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(equipment_id) REFERENCES equipment(id),FOREIGN KEY(connection_id) REFERENCES connections(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS incidents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,notice TEXT NOT NULL,status ENUM('investigating','identified','monitoring','resolved') NOT NULL DEFAULT 'investigating',planned BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
